CREATE DATABASE IF NOT EXISTS placement_db; USE placement_db;
CREATE TABLE users(id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(100) NOT NULL,email VARCHAR(150) UNIQUE NOT NULL,password VARCHAR(255) NOT NULL,role ENUM('student','company','admin') NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE students(id INT AUTO_INCREMENT PRIMARY KEY,user_id INT UNIQUE NOT NULL,register_no VARCHAR(50) UNIQUE NOT NULL,department VARCHAR(100),year INT,cgpa DECIMAL(4,2),phone VARCHAR(20),gender VARCHAR(20),date_of_birth DATE,address TEXT,resume VARCHAR(255),FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE companies(id INT AUTO_INCREMENT PRIMARY KEY,user_id INT UNIQUE NOT NULL,company_name VARCHAR(150) NOT NULL,phone VARCHAR(20),website VARCHAR(200),address TEXT,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE skills(id INT AUTO_INCREMENT PRIMARY KEY,skill_name VARCHAR(100) UNIQUE NOT NULL);
CREATE TABLE student_skills(id INT AUTO_INCREMENT PRIMARY KEY,student_id INT NOT NULL,skill_id INT NOT NULL,UNIQUE(student_id,skill_id),FOREIGN KEY(student_id) REFERENCES students(id) ON DELETE CASCADE,FOREIGN KEY(skill_id) REFERENCES skills(id) ON DELETE CASCADE);
CREATE TABLE jobs(id INT AUTO_INCREMENT PRIMARY KEY,company_id INT NOT NULL,job_title VARCHAR(150) NOT NULL,description TEXT,location VARCHAR(150),salary VARCHAR(100),min_cgpa DECIMAL(4,2) DEFAULT 0,eligible_department VARCHAR(100) DEFAULT 'All',eligible_year INT DEFAULT 0,deadline DATE,status ENUM('Open','Closed') DEFAULT 'Open',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(company_id) REFERENCES companies(id) ON DELETE CASCADE);
CREATE TABLE applications(id INT AUTO_INCREMENT PRIMARY KEY,student_id INT NOT NULL,job_id INT NOT NULL,status ENUM('Applied','Shortlisted','Selected','Rejected') DEFAULT 'Applied',applied_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,UNIQUE(student_id,job_id),FOREIGN KEY(student_id) REFERENCES students(id) ON DELETE CASCADE,FOREIGN KEY(job_id) REFERENCES jobs(id) ON DELETE CASCADE);
